import React, { useState, useEffect } from 'react';
import api from '../api';

const AdminFleetMonitor = ({ showToast }) => {
    const [devices, setDevices] = useState([]);
    const [users, setUsers] = useState([]);

    const loadData = async () => {
        try {
            const [devRes, usrRes] = await Promise.all([api.get('/admin/devices'), api.get('/admin/users')]);
            setDevices(devRes.data);
            setUsers(usrRes.data);
        } catch (err) {
            showToast('Admin privileges required.', 'error');
        }
    };

    useEffect(() => {
        loadData();
    }, []);

    const toggleDevice = async (id) => {
        try {
            const res = await api.post(`/admin/devices/${id}/toggle`);
            setDevices(devices.map(d => (d.id === id ? res.data : d)));
            showToast(`${res.data.name} is now ${res.data.online ? 'Online' : 'Offline'}.`, res.data.online ? 'success' : 'warning');
        } catch (err) {
            showToast('Failed to update gate state', 'error');
        }
    };

    const approvePayout = async (id) => {
        try {
            const res = await api.post(`/admin/users/${id}/payout`);
            showToast(res.data.message, 'success');
            loadData();
        } catch (err) {
            showToast('Payout failed', 'error');
        }
    };

    return (
        <div className="space-y-6">
            <div className="liquid-glass rounded-[30px] overflow-hidden">
                <div className="p-6 border-b border-white/10 flex flex-wrap items-center justify-between gap-4">
                    <div>
                        <h2 className="text-lg font-bold text-white">IoT Hardware Fleet</h2>
                        <p className="text-xs text-white/55">Manage Raspberry Pi 4 &amp; ESP32 turnstile nodes in real time.</p>
                    </div>
                    <span className="px-3.5 py-1 rounded-full text-xs font-mono bg-white/10 text-white/80 border border-white/15">Heartbeat: 5s</span>
                </div>

                <div className="overflow-x-auto">
                    <table className="w-full text-left border-collapse">
                        <thead>
                        <tr className="bg-white/[0.03] text-[11px] font-mono uppercase tracking-wider text-white/45 border-b border-white/10">
                            <th className="py-3.5 px-6">Gate Node</th>
                            <th className="py-3.5 px-6">Hardware ID</th>
                            <th className="py-3.5 px-6">Venue</th>
                            <th className="py-3.5 px-6">Scans</th>
                            <th className="py-3.5 px-6">Heartbeat</th>
                            <th className="py-3.5 px-6 text-right">State</th>
                        </tr>
                        </thead>
                        <tbody className="divide-y divide-white/10 text-sm">
                        {devices.map(dev => (
                            <tr key={dev.id} className="hover:bg-white/[0.03] transition">
                                <td className="py-4 px-6 font-semibold text-white flex items-center gap-2.5">
                                    <span className={`w-2.5 h-2.5 rounded-full ${dev.online ? 'bg-emerald-400 shadow-[0_0_10px_#34d399]' : 'bg-rose-400'}`}></span>
                                    <span>{dev.name}</span>
                                </td>
                                <td className="py-4 px-6 font-mono text-xs text-white/65">{dev.hardwareMac}</td>
                                <td className="py-4 px-6 text-white/70 text-xs">{dev.venue}</td>
                                <td className="py-4 px-6 font-mono font-bold text-white">{dev.scansProcessed}</td>
                                <td className="py-4 px-6 font-mono text-xs text-white/50">{dev.online ? dev.lastHeartbeat : 'Offline'}</td>
                                <td className="py-4 px-6 text-right">
                                    <button onClick={() => toggleDevice(dev.id)} className={`px-4 py-1.5 rounded-full text-xs font-semibold transition ${dev.online ? 'bg-emerald-400/20 text-emerald-200 border border-emerald-300/35 hover:bg-rose-400/20 hover:text-rose-200' : 'bg-rose-400/20 text-rose-200 border border-rose-300/35 hover:bg-emerald-400/20 hover:text-emerald-200'}`}>
                                        {dev.online ? 'Online' : 'Offline'}
                                    </button>
                                </td>
                            </tr>
                        ))}
                        </tbody>
                    </table>
                </div>
            </div>

            <div className="liquid-glass rounded-[30px] overflow-hidden">
                <div className="p-6 border-b border-white/10">
                    <h3 className="text-lg font-bold text-white">Identities &amp; Organizer Settlements</h3>
                    <p className="text-xs text-white/55">RBAC directory and instant SEPA balance payouts.</p>
                </div>
                <div className="overflow-x-auto">
                    <table className="w-full text-left border-collapse">
                        <thead>
                        <tr className="bg-white/[0.03] text-[11px] font-mono uppercase tracking-wider text-white/45 border-b border-white/10">
                            <th className="py-3.5 px-6">Name</th>
                            <th className="py-3.5 px-6">Email</th>
                            <th className="py-3.5 px-6">Role</th>
                            <th className="py-3.5 px-6">Balance</th>
                            <th className="py-3.5 px-6 text-right">Action</th>
                        </tr>
                        </thead>
                        <tbody className="divide-y divide-white/10 text-sm">
                        {users.map(u => (
                            <tr key={u.id} className="hover:bg-white/[0.03] transition">
                                <td className="py-4 px-6 font-semibold text-white">{u.fullName}</td>
                                <td className="py-4 px-6 font-mono text-xs text-white/60">{u.email}</td>
                                <td className="py-4 px-6">
                                    <span className="px-3 py-0.5 rounded-full text-[11px] font-mono bg-white/10 text-white/85 border border-white/15">{u.role}</span>
                                </td>
                                <td className="py-4 px-6 font-mono text-emerald-300 font-bold">
                                    {u.role === 'ORGANIZER' ? `${Number(u.netBalance).toLocaleString()} RON` : '—'}
                                </td>
                                <td className="py-4 px-6 text-right">
                                    {u.role === 'ORGANIZER' && Number(u.netBalance) > 0 ? (
                                        <button onClick={() => approvePayout(u.id)} className="px-4 py-1.5 rounded-full glass-pill-btn text-xs font-bold">
                                            Settle Balance
                                        </button>
                                    ) : (
                                        <span className="text-xs font-mono text-white/40">Verified</span>
                                    )}
                                </td>
                            </tr>
                        ))}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
};

export default AdminFleetMonitor;
